96	sealed class OrderStore
97	{
98	    readonly Dictionary<string, Order> _d = new(); readonly object _g = new();
99	    public void Put(string id, Order o) { lock (_g) _d[id] = o; }
100	    public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
101	}
102	
103	sealed class Metrics
104	{
105	    readonly Dictionary<string, long> _c = new(); readonly object _g = new();
106	    public void Inc(string name, string? label = null)
107	    {
108	        var k = label is null ? name : name + "{result=\"" + label + "\"}";
109	        lock (_g) _c[k] = _c.GetValueOrDefault(k) + 1;
110	    }
111	    static readonly double[] Buckets = { 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000 };
112	    readonly long[] _hist = new long[Buckets.Length + 1]; double _latSum; long _latCount;
113	    public void ObserveLatency(double ms)
114	    {
115	        lock (_g) { _latSum += ms; _latCount++; int i = 0; while (i < Buckets.Length && ms > Buckets[i]) i++; _hist[i]++; }
116	    }
117	    public string Render(int depth, string version)
118	    {
119	        lock (_g)
120	        {
121	            var sb = new System.Text.StringBuilder();
122	            foreach (var kv in _c.OrderBy(k => k.Key)) sb.Append("oc_").Append(kv.Key).Append(' ').Append(kv.Value).Append('\n');
123	            sb.Append("oc_notify_queue_depth ").Append(depth).Append('\n');
124	            long cum = 0;
125	            for (int i = 0; i < Buckets.Length; i++) { cum += _hist[i]; sb.Append("oc_request_latency_ms_bucket{le=\"").Append(Buckets[i]).Append("\"} ").Append(cum).Append('\n'); }
126	            cum += _hist[Buckets.Length]; sb.Append("oc_request_latency_ms_bucket{le=\"+Inf\"} ").Append(cum).Append('\n');
127	            sb.Append("oc_request_latency_ms_sum ").Append(Math.Round(_latSum, 1)).Append('\n').Append("oc_request_latency_ms_count ").Append(_latCount).Append('\n');
128	            sb.Append("oc_gc_heap_bytes ").Append(GC.GetTotalMemory(false)).Append('\n');
129	            sb.Append("oc_working_set_bytes ").Append(Environment.WorkingSet).Append('\n');
130	            sb.Append("oc_gc_collections_gen2 ").Append(GC.CollectionCount(2)).Append('\n');
131	            sb.Append("oc_info{version=\"").Append(version).Append("\"} 1\n");
132	            return sb.ToString();
133	        }
134	    }
135	}
