137	sealed class JsonlLog
138	{
139	    readonly string _p; readonly string _v; readonly object _g = new();
140	    public JsonlLog(string p, string v) { _p = p; _v = v; }
141	    public void Write(object o)
142	    {
143	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
144	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
145	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
146	    }
147	}
